sys_script_include.script:
var PTAGGeo = Class.create();
PTAGGeo.prototype = {
    // Target Geo is a reference to cmn_location, limited to the regions listed in this property.
    PROP: 'x_snc_ptag_engage.target_geo_options',

    initialize: function () {},

    ids: function () {
        var raw = String(gs.getProperty(this.PROP, '') || '');
        var out = [];
        raw.split(',').forEach(function (s) {
            s = s.trim();
            if (/^[0-9a-f]{32}$/.test(s) && out.indexOf(s) < 0) out.push(s);
        });
        return out;
    },

    // [{sys_id, name}] in property order; ids with no location record are skipped.
    options: function () {
        var ids = this.ids(), byId = {}, out = [];
        if (!ids.length) return out;
        var g = new GlideRecord('cmn_location');
        g.addQuery('sys_id', 'IN', ids.join(','));
        g.query();
        while (g.next()) byId[g.getUniqueValue()] = String(g.getValue('name'));
        ids.forEach(function (id) { if (byId[id]) out.push({sys_id: id, name: byId[id]}); });
        return out;
    },

    names: function () {
        return this.options().map(function (o) { return o.name; });
    },

    isAllowed: function (id) {
        return !!id && this.ids().indexOf(String(id)) >= 0;
    },

    refQual: function () {
        var ids = this.ids();
        return ids.length ? 'sys_idIN' + ids.join(',') : 'sys_id=-1';
    },

    type: 'PTAGGeo'
};
